  g.text(aStr).font({size:fs,fill:aCol}).attr({x:cx-58*s,y:cy+4*s});
  // Bond
  g.line(cx-24*s,cy,cx-12*s,cy).stroke({color:BLK,width:bw});
  // CH
  g.text('CH').font({size:fs,fill:BLK}).attr({x:cx-10*s,y:cy+4*s});
  // Bond
  g.line(cx+12*s,cy,cx+14*s,cy).stroke({color:BLK,width:bw});
  // C
  g.text('C').font({size:fs,fill:BLK}).attr({x:cx+15*s,y:cy+4*s});
  // Carboxyl end
  g.text(cStr).font({size:fs,fill:cCol}).attr({x:cx+28*s,y:cy+4*s});
  // Bond down
  g.line(cx-2*s,cy+8*s,cx-2*s,cy+20*s).stroke({color:BLK,width:bw});
  // CH3
  g.text('CH\u2083').font({size:fs*0.85,fill:BLK,'text-anchor':'middle'}).attr({x:cx-2*s,y:cy+32*s});
  return g;
}

function drawBracket(parent,x,y1,y2){
  parent.line(x,y1,x,y2).stroke({color:BLK,width:1.5});
  parent.line(x,y1,x+6,y1).stroke({color:BLK,width:1.5});
  parent.line(x,y2,x+6,y2).stroke({color:BLK,width:1.5});
}
function drawBracketR(parent,x,y1,y2){
  parent.line(x,y1,x,y2).stroke({color:BLK,width:1.5});
  parent.line(x-6,y1,x,y1).stroke({color:BLK,width:1.5});
  parent.line(x-6,y2,x,y2).stroke({color:BLK,width:1.5});
}

