// ─── Net charge view ───
function drawChargeBadge(parent,cx,cy,charge){
  var col=charge>0?MAGENTA:(charge<0?BLUE:'#4CAF50');
  var txt=charge>0?'+1':(charge<0?'\u22121':'0');
  parent.rect(44,28).attr({x:cx-22,y:cy-14,rx:6,fill:col,opacity:0.15,stroke:col,'stroke-width':2});
  parent.text(txt).font({size:16,fill:col,'text-anchor':'middle','font-weight':'bold'}).attr({x:cx,y:cy+6});
}

