// ─── Connecting arrows ───
function connArrow(x1,y1,x2,y2){
  draw.line(x1,y1,x2,y2).stroke({color:BLK,width:0.8});
  var ang=Math.atan2(y2-y1,x2-x1);
  var ax=x2-7*Math.cos(ang-0.35),ay=y2-7*Math.sin(ang-0.35);
  var bx=x2-7*Math.cos(ang+0.35),by=y2-7*Math.sin(ang+0.35);
  draw.polygon(x2+','+y2+' '+ax+','+ay+' '+bx+','+by).fill(BLK);
}
connArrow(SX-80,structYs[0],px(0)+8,py(0.3));
