// ─── Highlight ──
highlightRect=draw.rect(200,80).attr({rx:8,fill:'none',stroke:'#FF9800','stroke-width':2.5,opacity:0});

// ─── State ───
var curEquiv=0;
var panelMode='formulas';
var curStep=0;

function getActiveStruct(e){
  if(e<0.25)return 0;
  if(e<0.75)return 1;
  if(e<1.25)return 2;
  if(e<1.75)return 3;
  return 4;
}

function updateMarker(){
  var pH=pHFromEquiv(curEquiv);
  var mx=px(curEquiv),my=py(pH);
  marker.attr({cx:mx,cy:my});
  phLabel.text('pH = '+pH.toFixed(2)).attr({x:mx+12,y:my-10});
  // Highlight
  var idx=getActiveStruct(curEquiv);
  var sg=structGroups[idx];
  var bb=sg.bbox();
  highlightRect.attr({x:bb.x-8,y:bb.y-8,width:bb.width+16,height:bb.height+16,opacity:1});
}

function update_equivalents(v){
  curEquiv=v;
  updateMarker();
}

function toggle_rightPanelView(mode){
  panelMode=mode;
  for(var i=0;i<5;i++){
    if(mode==='formulas'){structGroups[i].show();chargeGroups[i].hide();}
    else{structGroups[i].hide();chargeGroups[i].show();}
  }
  updateMarker();
}

