var steps=[
  {title:'Fully protonated start',narration:'At 0 equivalents of base the curve sits at low pH and the linked structure is the fully protonated cation (magenta H\u2083N\u207A and intact COOH), carrying a net +1 charge.',state:{equivalents:0,rightPanelView:'formulas'}},
  {title:'First buffering region (pKa\u2081)',narration:'At 0.5 equivalents the marker rests on the flat leg at pH 2.34; the right panel shows a 50:50 bracketed pair of cation and zwitterion \u2014 the hallmark of a pKa, where two adjacent species coexist equally.',state:{equivalents:0.5,rightPanelView:'formulas'}},
  {title:'Isoelectric point',narration:'At 1.0 equivalent the curve jumps steeply through pH 6.01 and the linked structure is the zwitterion alone; in net-charge view its +1 and \u22121 cancel to zero, showing why this is the isoelectric (no-net-charge) form.',state:{equivalents:1.0,rightPanelView:'charge'}},
  {title:'Second buffering region (pKa\u2082)',narration:'At 1.5 equivalents the marker sits on the upper flat leg at pH 9.69, where the zwitterion and the fully deprotonated anion (blue H\u2082N) coexist 50:50; beyond 2.0 equivalents only the net \u22121 anion remains.',state:{equivalents:1.5,rightPanelView:'formulas'}}
];

function applyStep(idx){
  curStep=idx;
  var s=steps[idx];
  curEquiv=s.state.equivalents;
  document.getElementById('equivalentsInput').value=curEquiv;
  document.getElementById('equivalentsVal').value=curEquiv.toFixed(2);
  panelMode=s.state.rightPanelView;
  var radios=document.querySelectorAll('input[name=panelView]');
  for(var i=0;i<radios.length;i++)radios[i].checked=(radios[i].value===panelMode);
  toggle_rightPanelView(panelMode);
  updateMarker();
  document.getElementById('demoNarration').textContent=s.narration;
  document.getElementById('stepLabel').textContent=(idx+1)+'/'+steps.length;
}

function nextStep(){if(curStep<steps.length-1)applyStep(curStep+1);}
function prevStep(){if(curStep>0)applyStep(curStep-1);}

// Init
applyStep(0);
